// Expected failures live in the type
sealed interface SignIn {
  data class Success(val token: String) : SignIn
  data object WrongPassword : SignIn
  data class Offline(val cause: IOException) : SignIn
}

suspend fun signIn(email: String, password: String): SignIn = try {
  SignIn.Success(api.login(email, password))
} catch (e: HttpException) {
  if (e.code() == 401) SignIn.WrongPassword else throw e
} catch (e: IOException) {
  SignIn.Offline(e)
}

// when over a sealed result — the compiler checks you handled everything
when (val r = signIn(email, password)) {
  is SignIn.Success -> store(r.token)
  SignIn.WrongPassword -> showError()
  is SignIn.Offline -> showRetry()
}

