fun render(rows: List<Row>) {
    val first = rows.firstOrNull() ?: return showEmptyState()  // ✅ empty is expected here
    // val bad = rows.first()                                  // ❌ NoSuchElementException

    val third = rows.getOrNull(2)
    val label = rows.getOrElse(2) { Row.Placeholder }

    // single() tells "none" from "more than one"; singleOrNull() hides both
    // rows.single { it.isPrimary }                            // throws either way
    val primary = rows.singleOrNull { it.isPrimary }           // null on 0 AND on 2+

    // max()/min() are back since 1.7 and throw on empty
    // val newest = rows.maxOf { it.updatedAt }                // ❌ on an empty list
    val newest = rows.maxOfOrNull { it.updatedAt } ?: 0L
    val biggest = rows.maxByOrNull { it.size }

    show(first, third, label, primary, newest, biggest)
}

